import{c as a,Q as s,j as t,m as o}from"./chunks/framework.DVSyX6JR.js";const b=JSON.parse('{"title":"Power saving","description":"","frontmatter":{},"headers":[],"relativePath":"docs/power-saving.md","filePath":"docs/power-saving.md"}'),n={name:"docs/power-saving.md"};function r(i,e,p,l,d,h){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="power-saving" tabindex="-1">Power saving <a class="header-anchor" href="#power-saving" aria-label="Permalink to &quot;Power saving&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Power saving lets a repeater sleep when it has nothing to transmit. This is useful for battery-powered or solar-powered nodes.</p><p>The default is <strong>off</strong>. Many repeaters are fixed relay or backbone nodes and should not sleep unexpectedly.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>powersaving          — show current state</span></span>
<span class="line"><span>powersaving on       — enable power saving</span></span>
<span class="line"><span>powersaving off      — disable power saving</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get power.stats      — show sleep/wake statistics</span></span>
<span class="line"><span>clear power.stats    — reset statistics</span></span></code></pre></div><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><p>When power saving is enabled:</p><ul><li>The repeater sleeps only when there is <strong>no outbound work pending</strong>.</li><li>Bridge or WiFi mode <strong>blocks sleep</strong> — a bridged repeater stays awake.</li><li><strong>ESP32 boards</strong> wake via LoRa DIO1 or timer where supported.</li><li><strong>nRF52 boards</strong> use event/interrupt sleep.</li></ul><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><p><code>get power.stats</code> shows how often and how long the repeater has slept. Stats are RAM-only and reset on reboot or when cleared with <code>clear power.stats</code>.</p><h2 id="daily-reboot-timer" tabindex="-1">Daily reboot timer <a class="header-anchor" href="#daily-reboot-timer" aria-label="Permalink to &quot;Daily reboot timer&quot;">​</a></h2><p>Repeater-only and TCP bridge repeater builds also support an optional uptime-based reboot timer. This is separate from power saving and is disabled by default.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set reboot.daily on</span></span>
<span class="line"><span>set reboot.interval 24</span></span>
<span class="line"><span>get reboot</span></span></code></pre></div><p>The interval is configured in hours from <code>1</code> to <code>168</code>. When the timer expires, the repeater waits until the outbound TX queue is idle and then reboots. RS232 and ESP-NOW bridge builds do not include this timer.</p>`,15)])])}const u=a(n,[["render",r]]);export{b as __pageData,u as default};
